gOv(){return"\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0438\u0437 \u043f\u0440\u043e\u0444\u0438\u043b\u044f \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u0430. \u041e\u043d\u0438 \u0432\u043e\u0439\u0434\u0443\u0442 \u043f\u043e \u043a\u043e\u0434\u0443 \u0438\u0437 \u043f\u0438\u0441\u044c\u043c\u0430."},
gyG(){return"\u0421\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u044b"},
gIR(){return"\u041f\u043e\u044f\u0441 \u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d"},
