grG(){return"\u0414\u043e\u0441\u0442\u0443\u043f\u044b"},
gxT(){return"\u041a\u0442\u043e \u0441 \u043a\u0430\u043a\u0438\u043c\u0438 \u0433\u0440\u0443\u043f\u043f\u0430\u043c\u0438 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442"},
gtN(){return"\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u0442\u0440\u0435\u043d\u0435\u0440"},
