gOy(){return"\u0422\u0440\u0435\u043d\u0435\u0440\u044b \u0438 \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u044b"},
gZ4(){return"3 \xb7 \u0421\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u044b"},
gZ2(){return"\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u0435 \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u043e\u0432 \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b: \u043e\u043d\u0438 \u0432\u0438\u0434\u044f\u0442 \u043f\u043e\u044f\u0441, \u043f\u043e\u043b\u043e\u0441\u043a\u0438, \u0437\u0430\u0434\u0430\u043d\u0438\u044f \u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b."},
gHL(){return"\u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u043f\u0435\u0440\u0432\u043e\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435. \u0421\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u044b \u0435\u0433\u043e \u0443\u0432\u0438\u0434\u044f\u0442, \u0430 \u0432\u044b \u0443\u0432\u0438\u0434\u0438\u0442\u0435, \u043a\u0442\u043e \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043b."},
gOw(){return"\u041f\u0440\u0438\u0433\u043b\u0430\u0448\u0430\u0439\u0442\u0435 \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u043e\u0432 \u0438\u0437 \u0438\u0445 \u043f\u0440\u043e\u0444\u0438\u043b\u044f \u0438\u043b\u0438 \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b. \u041e\u043d\u0438 \u0432\u0445\u043e\u0434\u044f\u0442 \u043f\u043e \u043a\u043e\u0434\u0443 \u0438\u0437 \u043f\u0438\u0441\u044c\u043c\u0430."},
gxa(){return"\u0422\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0442\u0440\u0435\u043d\u0435\u0440\u043e\u0432, \u0441\u043f\u043e\u0440\u0442\u0441\u043c\u0435\u043d\u044b \u043d\u0435 \u0432\u0438\u0434\u044f\u0442"},
gzm(){return"\u0427\u0442\u043e\u0431\u044b \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f Jita, \u043a\u043b\u0443\u0431 \u0445\u0440\u0430\u043d\u0438\u0442 \u0438 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0432\u0430\u0448\u0438 \u0434\u0430\u043d\u043d\u044b\u0435: \u0438\u043c\u044f, \u0434\u0430\u0442\u0443 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f, \u0433\u0440\u0443\u043f\u043f\u0443 \u0438 \u0440\u0430\u0441\u043f\u0438\u0441\u0430\u043d\u0438\u0435, \u043f\u043e\u0441\u0435\u0449\u0430\u0435\u043c\u043e\u0441\u0442\u044c, \u043f\u043e\u044f\u0441\u0430 \u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b, \u0434\u043e\u043c\u0430\u0448\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u044f \u0438 \u0436\u0443\u0440\u043d\u0430\u043b \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u043a, \u0432\u0438\u0434\u0435\u043e \u043f\u0440\u0438\u0451\u043c\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0432\u044b \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442\u0435, \u043c\u0435\u0434\u0438\u0446\u0438\u043d\u0441\u043a\u0438\u0435 \u0441\u043f\u0440\u0430\u0432\u043a\u0438 \u0438 \u0434\u0435\u043a\u043b\u0430\u0440\u0430\u0446\u0438\u044e \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f, \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b \u0438 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u044f. \u0414\u0430\u043d\u043d\u044b\u0435 \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u0432 \u0437\u0430\u0449\u0438\u0449\u0451\u043d\u043d\u043e\u0439 \u0431\u0430\u0437\u0435 \u0432 \u0415\u0421 (Supabase), \u0438\u0445 \u0432\u0438\u0434\u044f\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0440\u0435\u043d\u0435\u0440\u044b \u0432\u0430\u0448\u0438\u0445 \u0433\u0440\u0443\u043f\u043f, \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440 \u043a\u043b\u0443\u0431\u0430 \u0438 \u0432\u044b; \u043e\u043d\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u044e\u0442\u0441\u044f \u0438 \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0434\u043b\u044f \u0440\u0435\u043a\u043b\u0430\u043c\u044b; \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0432 \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0438\u043b\u0438 \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u0438\u0445 (\xab\u0415\u0449\u0451\xbb, \u0437\u0430\u0442\u0435\u043c \xab\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0438 \u0434\u0430\u043d\u043d\u044b\u0435\xbb). \u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435 \u0432 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0435 \u043a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438."},
