gXv(){return"\u041d\u0430\u043f\u043e\u043c\u043d\u0438\u043c \u0432 \u0434\u0435\u043d\u044c \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438 \u0438 \u0441\u043a\u0430\u0436\u0435\u043c, \u043a\u043e\u0433\u0434\u0430 \u0432\u044b\u0445\u043e\u0434\u0438\u0442\u044c. \u0412\u044b\u0445\u043e\u0434\u0438\u0448\u044c: \u043d\u0430\u0436\u043c\u0438 \xab\u0412\u044b\u0445\u043e\u0436\u0443 \u043d\u0430 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0443\xbb \u0432 \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u0438, \u0438 \u0442\u0440\u0435\u043d\u0435\u0440 \u0443\u0432\u0438\u0434\u0438\u0442 \u044d\u0442\u043e \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438."},
